CREATE TABLE whatsapp_entries (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, conversation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, ad_ref CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, offer_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, method VARCHAR(10) NOT NULL, certainty VARCHAR(5) NOT NULL, code VARCHAR(32) NULL, referral JSON NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), KEY whatsapp_entries_ad_idx (user_id,ad_ref,created_at), CONSTRAINT whatsapp_entries_method_ck CHECK (method IN ('ad','code_link','code_text')), CONSTRAINT whatsapp_entries_certainty_ck CHECK (certainty IN ('alta','media','baja')), CONSTRAINT whatsapp_entries_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT whatsapp_entries_conversation_fk FOREIGN KEY (conversation_id,user_id) REFERENCES whatsapp_conversations(id,user_id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci